glm::vec3 r = pj->position - pi->position;
float rLen = std::sqrt(glm::dot(r, r));
if (rLen > 0.0f && rLen < settings.h) {
    float q = rLen / settings.h;
    float gradSpiky = settings.spikyGrad * (1.0f / (settings.h * settings.h * settings.h)) * (1.0f / (std::pow(1.0f - q, 2.0f)));
    glm::vec3 gradDir = r / rLen;
    return (pi->mass * pj->mass / (pi->density * pj->density)) * gradSpiky * gradDir;
} else {
    return glm::vec3(0.0f);
}

